var a={en:`API response target is 800 ms; PSP calls sometimes take 3 s and warehouse holds another 2 s. Which status can the interface truthfully show?`,ua:`API має відповідати за 800 мс; PSP інколи працює 3 с, складський резерв — ще 2 с. Який статус можна чесно показати користувачу?`};var n={en:[`Compare blocking, asynchronous and hybrid order workflows.`,`Mark precisely when payment and stock are confirmed.`,`Write ADR for refunds, retries and user-facing pending states.`],ua:[`Порівняй блокувальний, асинхронний та гібридний процес.`,`Познач точку підтвердження оплати й складу.`,`Напиши ADR про повернення, повтори та очікування.`]};var r=[{en:`No success status precedes required acknowledgements.`,ua:`Успіх не показується до необхідних підтверджень.`},{en:`Timeouts cannot silently create duplicate payments.`,ua:`Таймаути не породжують непомітних подвійних платежів.`}];var t={scenario:a,tasks:n,checks:r};export{r as checks,t as default,a as scenario,n as tasks};